import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1786903141000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is configured through environment variables. See the <a href="/reference/environment">environment variable reference</a> for the full table.</p><h2 id="getting-a-token" tabindex="-1">Getting a token <a class="header-anchor" href="#getting-a-token" aria-label="Permalink to “Getting a token”">​</a></h2><p>In the Opengist web UI: <strong>Settings → Access Tokens → Generate new token</strong>. Opengist shows the value once; it starts with <code>og_</code>.</p><p>The server warns on startup if the token does not start with <code>og_</code>, because the most common mistake is pasting an account password instead.</p><h2 id="required-scopes" tabindex="-1">Required scopes <a class="header-anchor" href="#required-scopes" aria-label="Permalink to “Required scopes”">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>What it unlocks</th></tr></thead><tbody><tr><td><code>gist:read</code></td><td>Reading gists, including your private and unlisted ones</td></tr><tr><td><code>gist:write</code></td><td><code>create_gist</code>, <code>update_gist</code>, <code>delete_gist*</code>, <code>fork_gist</code></td></tr><tr><td><code>user:read</code></td><td><code>get_user</code></td></tr><tr><td><code>user:write</code></td><td><code>set_gist_like</code> only</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">A token without <code>gist:read</code> fails quietly</p><p>The API does not reject it. It silently returns only public gists, so your own private ones simply appear not to exist. If a gist you can see in the browser is missing from <code>list_gists</code>, check the scope first.</p></div><p>If you only want the model to read, the honest way to do it is a token with <code>gist:read</code> and <code>user:read</code> and nothing else. <code>OPENGIST_READ_ONLY=true</code> is the convenience version of the same idea — it stops the write tools from being registered at all — but it is enforced by this server, not by Opengist. See <a href="/guide/security#what-actually-holds">Security</a>.</p><h2 id="the-instance-url" tabindex="-1">The instance URL <a class="header-anchor" href="#the-instance-url" aria-label="Permalink to “The instance URL”">​</a></h2><p><code>OPENGIST_URL</code> is the root of your instance, not the API path:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">OPENGIST_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">https://gist.example.com</span></span></code></pre></div><p>A trailing slash is stripped, and a trailing <code>/api</code> is accepted and removed rather than producing <code>/api/api</code>.</p><p>The server refuses to start if the URL is malformed, uses a protocol other than http/https, or contains a username or password — credentials in the URL would be sent on every request in addition to the bearer token and would surface in error messages.</p><p>Plain <code>http://</code> to anything other than a loopback address produces a warning and then continues. The token and every gist would travel unencrypted; use <code>https://</code>.</p><div class="tip custom-block"><p class="custom-block-title">Set <code>external-url</code> on the instance</p><p>If Opengist&#39;s own <code>external-url</code> (<code>OG_EXTERNAL_URL</code>) is not configured, the URLs it reports — and that this server passes through — point at <code>localhost</code>. The gists are correct, the links are useless.</p></div><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to “TLS”">​</a></h2><p>For an instance with a self-signed or internal-CA certificate:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">OPENGIST_INSECURE_TLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span></code></pre></div><p>This is scoped to the connection to your Opengist instance through a dedicated undici dispatcher. It does <strong>not</strong> set <code>NODE_TLS_REJECT_UNAUTHORIZED</code>, so it cannot weaken any other request the process makes, and it is only applied to requests whose origin matches <code>OPENGIST_URL</code>.</p><p>It still turns off certificate validation for that connection, which means anyone able to intercept it can read your token. Installing the CA certificate in the system trust store, or using <code>NODE_EXTRA_CA_CERTS</code>, is strictly better where it is an option.</p><h2 id="read-only-mode" tabindex="-1">Read-only mode <a class="header-anchor" href="#read-only-mode" aria-label="Permalink to “Read-only mode”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">OPENGIST_READ_ONLY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span></code></pre></div><p>The six write tools — <code>create_gist</code>, <code>update_gist</code>, <code>delete_gist_files</code>, <code>delete_gist</code>, <code>fork_gist</code>, <code>set_gist_like</code> — are not registered. The model does not see them in <code>tools/list</code> and cannot call them, rather than being told &quot;no&quot; after asking.</p><p>Any value other than the exact string <code>true</code> counts as false. <code>1</code>, <code>yes</code> and <code>TRUE</code> all leave the write tools enabled.</p>`,25)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};